const lockOperatorResultAuthority = `-- name: LockOperatorResultAuthority :one
SELECT tournament.id AS tournament_id,
    tournament.state AS tournament_state,
    roster.id AS roster_id,
    series.id AS series_id,
    series.revision AS authority_revision,
    projection.id AS projection_revision_id,
    projection.revision_number AS projection_revision
FROM series
JOIN rosters AS roster
    ON roster.id = series.roster_id
    AND roster.tournament_id = series.tournament_id
JOIN tournaments AS tournament
    ON tournament.id = roster.tournament_id
JOIN LATERAL (
    SELECT revision.id, revision.revision_number
    FROM projection_revisions AS revision
    WHERE revision.tournament_id = tournament.id
        AND revision.roster_id = roster.id AND revision.state = 'published'
    FOR UPDATE
) AS projection ON TRUE
WHERE tournament.id = $1
    AND series.id = $2
FOR UPDATE OF tournament, roster, series
`

type LockOperatorResultAuthorityParams struct {
	TournamentID uuid.UUID
	SeriesID     uuid.UUID
}

type LockOperatorResultAuthorityRow struct {
	TournamentID         uuid.UUID
	TournamentState      string
	RosterID             uuid.UUID
	SeriesID             uuid.UUID
	AuthorityRevision    int64
	ProjectionRevisionID uuid.UUID
	ProjectionRevision   int64
}

func (q *Queries) LockOperatorResultAuthority(ctx context.Context, arg LockOperatorResultAuthorityParams) (LockOperatorResultAuthorityRow, error) {
	row := q.db.QueryRow(ctx, lockOperatorResultAuthority, arg.TournamentID, arg.SeriesID)
	var i LockOperatorResultAuthorityRow
	err := row.Scan(
		&i.TournamentID,
		&i.TournamentState,
		&i.RosterID,
		&i.SeriesID,
		&i.AuthorityRevision,
		&i.ProjectionRevisionID,
		&i.ProjectionRevision,
	)
	return i, err
}
